(() => {
const choice=document.getElementById('ev-type'); if(!choice)return;
const shares={bev:[76.91,'Battery electric','Battery-electric vehicles form the larger share of this saved registration snapshot. Charging access is a relevant planning question, but registrations alone do not quantify demand.'],phev:[23.09,'Plug-in hybrid','Plug-in hybrids account for a smaller share of the displayed registrations. Their actual electric driving and emissions depend on charging and usage, which this snapshot does not measure.']};
choice.addEventListener('change',()=>{const [share,name,note]=shares[choice.value];document.getElementById('ev-share').textContent=share.toFixed(2)+'%';const ring=document.getElementById('ev-ring');ring.style.background=`conic-gradient(#345eea 0% ${share}%,#c4cec1 ${share}% 100%)`;ring.setAttribute('aria-label',`${name} vehicles: ${share} percent of displayed registrations`);document.getElementById('ev-insight').textContent=note;});
const notes=['Load: Airflow schedules CSV ingestion into PostgreSQL. The current DAG repeats ingestion in two tasks.','Clean: Standardise column names, remove duplicate rows and drop missing records. This step reads the original CSV directly; dropping all incomplete rows may introduce bias.','Index: Send cleaned CSV rows to Elasticsearch. Bulk indexing and explicit schema validation would make this stage more robust.','Explore: Use Kibana to examine the saved registration distributions. These descriptive patterns do not establish environmental impact or causation.'];
const buttons=document.querySelectorAll('[data-ev-step]');buttons.forEach(button=>{button.style.cssText='padding:10px 14px;border:1px solid #345eea;border-radius:4px;cursor:pointer;background:white;color:#345eea';button.addEventListener('click',()=>{buttons.forEach(b=>{b.setAttribute('aria-pressed',String(b===button));b.style.background=b===button?'#345eea':'white';b.style.color=b===button?'white':'#345eea';});document.getElementById('ev-step-detail').textContent=notes[Number(button.dataset.evStep)];});});buttons[0].style.background='#345eea';buttons[0].style.color='white';
})();
